<script setup lang="ts">
import {ref,onMounted,onUnmounted,watch} from 'vue'
import {billingCall,billingOpen,billingLabels,labels,money,dateLabel,type BillingView,type PlanId,type Catalog} from '../integrations/firebase/billingSandbox'
const props=defineProps<{platform?:boolean;gymId?:string}>()
const view=ref<BillingView|null>(null),cat=ref<Catalog|null>(null),ids=ref<Partial<Record<PlanId,string>>>({}),busy=ref(false),message=ref(''),trialDays=ref(30);let version=0
const planIds:PlanId[]=['monthly','quarterly','semiannual','annual']
async function load(){const v=++version;busy.value=true;message.value='';view.value=null;cat.value=null;try{if(props.platform){const c=await billingCall<Catalog>('lfBillingCatalog');if(v!==version)return;cat.value=c;ids.value={...c.priceIds};if(props.gymId){const b=await billingCall<BillingView>('lfBillingAdminState',{gymId:props.gymId});if(v===version)view.value=b}}else{const b=await billingCall<BillingView>('lfBillingStatus');if(v===version)view.value=b}}catch(e){if(v===version)message.value=(e as Error).message}finally{if(v===version)busy.value=false}}
async function action(name:string,data:Record<string,unknown>={}){if(busy.value)return;const v=version;busy.value=true;message.value='';try{if(name==='lfBillingSetCatalog'){const c=await billingCall<Catalog>(name,data);if(v===version){cat.value=c;ids.value={...c.priceIds};message.value='Catalogo Sandbox aggiornato.'}}else if(name==='lfBillingTrial'||name==='lfBillingAdjustTrial'){const b=await billingCall<BillingView>(name,data);if(v===version)view.value=b}else{const r=await billingCall<{url:string}>(name,data);if(v===version){await billingOpen(r.url);message.value='Al ritorno premi Aggiorna stato. Il pagamento è simulato.'}}}catch(e){if(v===version)message.value=(e as Error).message}finally{if(v===version)busy.value=false}}
watch(()=>props.gymId,()=>void load());onMounted(load);onUnmounted(()=>{version++})
</script>
<template><section class="panel stack lf16-billing"><div class="row between"><h2>{{platform?'Catalogo abbonamenti':'Abbonamento palestra'}}</h2><button class="secondary" :disabled="busy" @click="load">Aggiorna stato</button></div><p class="notice">STRIPE SANDBOX · Solo pagamenti simulati. Nessun blocco dell’app, nessun denaro reale.</p>
<div v-if="platform&&cat" class="stack"><p class="muted small">Crea quattro prezzi ricorrenti EUR in Stripe Sandbox e incolla gli ID price_. I prezzi verranno verificati sul server. Le modifiche valgono per i nuovi checkout, non per i contratti esistenti.</p><label v-for="p in planIds" :key="p">{{labels[p]}} · {{money(cat.plans.find(x=>x.id===p)?.cents||0)}}<input v-model="ids[p]" maxlength="100" placeholder="price_…" :disabled="busy"/></label><button class="primary" :disabled="busy||planIds.some(p=>!ids[p])" @click="action('lfBillingSetCatalog',{priceIds:ids})">Salva catalogo test</button></div>
<div v-if="view" class="stack"><h3>{{billingLabels[view.billing.status]||'Stato da verificare'}}</h3><p v-if="view.billing.plan">Piano: {{labels[view.billing.plan as PlanId]||view.billing.plan}}</p><p v-if="view.billing.status==='trial'">Scadenza prova: {{dateLabel(view.billing.trialEnd)}}</p><p v-if="view.billing.renewalAt">{{view.billing.cancelAtPeriodEnd?'Fine contratto':'Rinnovo previsto'}}: {{dateLabel(view.billing.renewalAt)}}</p><div v-if="platform&&gymId&&view.billing.trialEnd&&!view.billing.hasCustomer&&view.billing.status!=='exempt'" class="stack"><label>Giorni residui prova Sandbox (0 per simulare scadenza)<input type="number" min="0" max="365" step="1" v-model.number="trialDays"/></label><button class="secondary" :disabled="busy||!Number.isInteger(trialDays)||trialDays<0||trialDays>365" @click="action('lfBillingAdjustTrial',{gymId,days:trialDays})">Simula durata residua</button></div><p v-if="view.billing.status==='grace'">Tolleranza fino al {{dateLabel(view.billing.graceEnd)}}</p><template v-if="!platform"><button v-if="view.billing.status==='not_started'" class="primary" :disabled="busy" @click="action('lfBillingTrial')">Attiva 30 giorni di prova senza carta</button><div v-if="['trial','expired','not_started'].includes(view.billing.status)" class="lf16-plans"><article v-for="p in view.plans" :key="p.id" class="panel"><strong>{{labels[p.id]}}</strong><h3>{{money(p.cents)}}</h3><small>Ogni {{p.months}} {{p.months===1?'mese':'mesi'}} · {{money(Math.round(p.cents/p.months))}}/mese</small><p v-if="p.id==='annual'" class="small">Formula annuale</p><button v-if="p.configured&&view.billing.status==='expired'" class="secondary wide" :disabled="busy" @click="action('lfBillingCheckout',{plan:p.id})">Scegli piano test</button><small v-else-if="!p.configured" class="muted">Prezzo indicativo · non configurato</small></article></div><button v-if="view.billing.hasCustomer" class="secondary" :disabled="busy" @click="action('lfBillingPortal')">Gestisci abbonamento test</button></template></div><p v-if="busy" class="muted" role="status">Caricamento Sandbox…</p><p v-if="message" class="notice" role="status">{{message}}</p></section></template>
<style scoped>.lf16-plans{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,160px),1fr));gap:10px}.lf16-plans article{display:grid;gap:8px;min-width:0}.lf16-billing h3{margin:0}.lf16-billing input{width:100%;min-width:0}</style>
